/**
 * Jotform to Airtable connector.
 * When a Jotform submission arrives, look up the Airtable record by email and PATCH only the fields that are non-empty in the payload.
 */

export interface ConnectorConfig {
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  baseId: string;
  /** Airtable table name (e.g., "Table 1") */
  tableName: string;
  /** Airtable API key (personal access token). Can also be provided via AIRTABLE_API_KEY env var. */
  apiKey?: string;
  /** Injected fetch implementation (for testing). Defaults to global fetch. */
  fetch?: typeof fetch;
}

export interface JotformPayload {
  email: string;
  name?: string;
  phone?: string;
  address?: string;
  [key: string]: unknown;
}

export interface HandleResult {
  recordId: string;
}

/**
 * Escapes a value for use in an Airtable filterByFormula string literal.
 * According to the spec, '+' must be escaped as '\\+'. Also escape backslashes and single quotes.
 */
function escapeFormulaValue(value: string): string {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\+/g, '\\+');
}

/**
 * Builds a filterByFormula string to match a record by email.
 * Formula: {email} = 'escapedValue'
 */
function buildFilterByFormula(email: string): string {
  const escaped = escapeFormulaValue(email);
  return `{email} = '${escaped}'`;
}

async function airtableGet(
  config: ConnectorConfig,
  filterByFormula: string,
  fetchImpl: typeof fetch
): Promise<{ records: Array<{ id: string; fields: Record<string, unknown> }>; offset?: string }> {
  const url = new URL(`https://api.airtable.com/v0/${config.baseId}/${encodeURIComponent(config.tableName)}`);
  url.searchParams.set('filterByFormula', filterByFormula);
  url.searchParams.set('maxRecords', '1');

  const response = await fetchImpl(url.toString(), {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Airtable GET failed: ${response.status} ${response.statusText} at ${url.toString()}`);
  }

  return response.json();
}

async function airtablePatch(
  config: ConnectorConfig,
  recordId: string,
  fields: Record<string, unknown>,
  fetchImpl: typeof fetch
): Promise<{ id: string; fields: Record<string, unknown> }> {
  const url = `https://api.airtable.com/v0/${config.baseId}/${encodeURIComponent(config.tableName)}/${recordId}`;

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  });

  if (!response.ok) {
    throw new Error(`Airtable PATCH failed: ${response.status} ${response.statusText} at ${url}`);
  }

  return response.json();
}

/**
 * Main entry point. Processes a Jotform submission payload, finds the matching Airtable record by email,
 * and patches non-empty fields (name, phone, address) from the payload.
 *
 * @param payload - The parsed Jotform submission payload (must contain email).
 * @param config - Connector configuration including Airtable credentials.
 * @returns The updated Airtable record ID.
 * @throws Error if email is missing, no matching record found, or Airtable API returns non-2xx.
 */
export async function handle(payload: JotformPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required field
  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email');
  }

  const fetchImpl = config.fetch ?? fetch;
  const apiKey = config.apiKey ?? process.env.AIRTABLE_API_KEY;
  if (!apiKey) {
    throw new Error('Airtable API key not provided. Set config.apiKey or AIRTABLE_API_KEY env var.');
  }

  const fullConfig: Required<ConnectorConfig, 'apiKey'> = { ...config, apiKey };

  // Step 1: Find record by email
  const filter = buildFilterByFormula(payload.email);
  const getResult = await airtableGet(fullConfig, filter, fetchImpl);

  if (!getResult.records || getResult.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${payload.email}`);
  }

  const record = getResult.records[0];
  const recordId = record.id;

  // Step 2: Build fields to patch (only non-empty values from payload for mapped fields)
  const fieldsToPatch: Record<string, unknown> = {};
  const mappedFields: (keyof JotformPayload)[] = ['name', 'phone', 'address'];

  for (const field of mappedFields) {
    const value = payload[field];
    if (value !== undefined && value !== null && value !== '') {
      fieldsToPatch[field] = value;
    }
  }

  // If no fields to patch, we could skip the PATCH, but the spec expects a PATCH call? The plan says PATCH only fields that are empty.
  // We'll still call PATCH with empty fields? The example shows PATCH with fields. If fieldsToPatch is empty, we can skip and return.
  if (Object.keys(fieldsToPatch).length === 0) {
    return { recordId };
  }

  // Step 3: Patch the record
  await airtablePatch(fullConfig, recordId, fieldsToPatch, fetchImpl);

  return { recordId };
}

// Helper type to make apiKey required
type Required<T, K extends keyof T> = T & { [P in K]-?: never };

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

// Contract test (must be at top level with title 'contract')
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      baseId: 'appXXXXXXXXXXXXXX',
      tableName: 'Table 1',
      apiKey: 'test-api-key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('recXXXXXXXXXXXX');
  });
});

// Helper to create a valid config for tests
function createTestConfig(overrides: Partial<ConnectorConfig> = {}): ConnectorConfig {
  return {
    baseId: 'appXXXXXXXXXXXXXX',
    tableName: 'Table 1',
    apiKey: 'test-api-key',
    ...overrides,
  };
}

describe('handle', () => {
  it('happy path: finds record and patches non-empty fields', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET' && req.url.includes('/v0/appXXXXXXXXXXXXXX/Table%201')) {
        // Check filterByFormula
        expect(req.url).toContain("filterByFormula=%7Bemail%7D+%3D+%27user%40example.com%27");
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.method === 'PATCH' && req.url.includes('/v0/appXXXXXXXXXXXXXX/Table%201/recXXXXXXXXXXXX')) {
        // Check PATCH body
        expect(req.json).toEqual({
          fields: {
            name: 'John Doe',
            phone: '555-1234',
            address: '123 Main St',
          },
        });
        // Check auth header
        expect(req.headers.get('authorization')).toBe('Bearer test-api-key');
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'unexpected request' }, 404);
    });

    const payload: JotformPayload = {
      email: 'user@example.com',
      name: 'John Doe',
      phone: '555-1234',
      address: '123 Main St',
    };

    const result = await handle(payload, createTestConfig({ fetch }));
    expect(result.recordId).toBe('recXXXXXXXXXXXX');
    expect(calls.length).toBe(2);
  });

  it('auth mechanism: includes Bearer token in Authorization header', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        expect(req.headers.get('authorization')).toBe('Bearer test-api-key');
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.method === 'PATCH') {
        expect(req.headers.get('authorization')).toBe('Bearer test-api-key');
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({}, 404);
    });

    await handle(
      { email: 'user@example.com', name: 'Test' },
      createTestConfig({ fetch })
    );
  });

  it('field mapping: only includes non-empty fields from payload', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.method === 'PATCH') {
        // Payload has name and phone, but address is empty string -> should not be included
        expect(req.json).toEqual({
          fields: {
            name: 'Jane',
            phone: '555-0000',
          },
        });
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({}, 404);
    });

    const payload: JotformPayload = {
      email: 'user@example.com',
      name: 'Jane',
      phone: '555-0000',
      address: '', // empty string -> should be omitted
    };

    await handle(payload, createTestConfig({ fetch }));
    expect(calls.length).toBe(2);
  });

  it('throws on missing required field (email)', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200)); // should not be called
    const payload = { name: 'No Email' } as unknown as JotformPayload;

    await expect(handle(payload, createTestConfig({ fetch }))).rejects.toThrow('Missing required field: email');
  });

  it('throws on non-2xx response from Airtable GET', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Not found' }, 404));
    const payload: JotformPayload = { email: 'user@example.com' };

    await expect(handle(payload, createTestConfig({ fetch }))).rejects.toThrow('Airtable GET failed: 404 Not Found');
  });

  it('throws on non-2xx response from Airtable PATCH', async () => {
    const { fetch } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.method === 'PATCH') {
        return jsonResponse({ error: 'Invalid fields' }, 400);
      }
      return jsonResponse({}, 404);
    });

    const payload: JotformPayload = { email: 'user@example.com', name: 'Test' };

    await expect(handle(payload, createTestConfig({ fetch }))).rejects.toThrow('Airtable PATCH failed: 400 Bad Request');
  });

  it('escapes plus sign in email for filterByFormula', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        // Email: user+tag@example.com -> escaped as user\\+tag@example.com
        expect(req.url).toContain("filterByFormula=%7Bemail%7D+%3D+%27user%5C%2Btag%40example.com%27");
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.method === 'PATCH') {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({}, 404);
    });

    const payload: JotformPayload = { email: 'user+tag@example.com', name: 'Test' };
    await handle(payload, createTestConfig({ fetch }));
    expect(calls.length).toBe(2);
  });

  it('skips PATCH when no non-empty fields to update', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      // PATCH should not be called
      return jsonResponse({}, 404);
    });

    const payload: JotformPayload = { email: 'user@example.com', name: '', phone: '', address: '' };
    const result = await handle(payload, createTestConfig({ fetch }));
    expect(result.recordId).toBe('recXXXXXXXXXXXX');
    expect(calls.length).toBe(1); // only GET
  });
});

# Jotform to Airtable Connector

This connector processes a Jotform submission webhook payload, finds the corresponding Airtable record by email, and updates (PATCH) only the fields that are non-empty in the submission.

## What it does

1. Receives a Jotform submission payload (parsed JSON, must contain an `email` field).
2. Queries Airtable's List Records endpoint with a `filterByFormula` to locate the record where `{email} = 'submitted_email'`.
3. If a record is found, builds a PATCH payload containing only the fields from the submission that are non-empty (currently mapped: `name`, `phone`, `address`).
4. Sends a PATCH request to update that record.
5. Returns the Airtable record ID.

## Configuration

The connector requires the following configuration (provided via `ConnectorConfig`):

| Property | Description | Required | Environment Variable |
|----------|-------------|----------|----------------------|
| `baseId` | Airtable base ID (e.g., `appXXXXXXXXXXXXXX`) | Yes | — |
| `tableName` | Airtable table name (e.g., `Table 1`) | Yes | — |
| `apiKey` | Airtable Personal Access Token | Yes* | `AIRTABLE_API_KEY` |
| `fetch` | Injected `fetch` implementation (for testing) | No | — |

\* Either `config.apiKey` or the `AIRTABLE_API_KEY` environment variable must be set.

## Usage Example

```typescript
import { handle, ConnectorConfig } from './connector';

const config: ConnectorConfig = {
  baseId: 'appXXXXXXXXXXXXXX',
  tableName: 'Leads',
  apiKey: process.env.AIRTABLE_API_KEY, // or set directly
};

// Assuming you have parsed the Jotform webhook payload (after extracting from rawRequest if needed)
const jotformPayload = {
  email: 'user@example.com',
  name: 'John Doe',
  phone: '555-1234',
  address: '123 Main St',
};

try {
  const result = await handle(jotformPayload, config);
  console.log('Updated Airtable record:', result.recordId);
} catch (err) {
  console.error('Connector failed:', err.message);
}
```

## Assumptions

- The Jotform submission contains an `email` field that uniquely identifies the Airtable record.
- The Airtable table has a field named `email` that can be used in `filterByFormula`.
- Any field present in the Jotform payload that is not empty (non-empty string, not null, not undefined) should be PATCHed to Airtable.
- Fields that are empty in the Jotform payload should remain unchanged in Airtable (they are omitted from the PATCH body).
- The mapped fields are `name`, `phone`, and `address`. Additional fields can be added by modifying the `mappedFields` array in the connector.
- The Airtable API key has sufficient permissions to read and update records in the specified table.
- The connector does not handle multipart/form-data parsing; it expects the payload to already be the parsed JSON object (i.e., the content of the `rawRequest` field). If your platform delivers the raw multipart request, parse it before calling `handle`.
- Emails containing `+` are escaped as `\\+` in the `filterByFormula` per Airtable's formula syntax.
- Pagination is handled by requesting `maxRecords=1`; only the first matching record is used.

