async function airtablePatch(
  config: ConnectorConfig,
  recordId: string,
  fields: Record<string, unknown>,
  fetchImpl: typeof fetch
): Promise<{ id: string; fields: Record<string, unknown> }> {
  const url = `https://api.airtable.com/v0/${config.baseId}/${encodeURIComponent(config.tableName)}/${recordId}`;

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  });

  if (!response.ok) {
    throw new Error(`Airtable PATCH failed: ${response.status} ${response.statusText} at ${url}`);
  }

  return response.json();
}

/**
 * Main entry point. Processes a Jotform submission payload, finds the matching Airtable record by email,
 * and patches non-empty fields (name, phone, address) from the payload.
 *
 * @param payload - The parsed Jotform submission payload (must contain email).
 * @param config - Connector configuration including Airtable credentials.
 * @returns The updated Airtable record ID.
 * @throws Error if email is missing, no matching record found, or Airtable API returns non-2xx.
 */
export async function handle(payload: JotformPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required field
  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email');
  }

  const fetchImpl = config.fetch ?? fetch;
  const apiKey = config.apiKey ?? process.env.AIRTABLE_API_KEY;
  if (!apiKey) {
    throw new Error('Airtable API key not provided. Set config.apiKey or AIRTABLE_API_KEY env var.');
  }

  const fullConfig: Required<ConnectorConfig, 'apiKey'> = { ...config, apiKey };

  // Step 1: Find record by email
  const filter = buildFilterByFormula(payload.email);
  const getResult = await airtableGet(fullConfig, filter, fetchImpl);

  if (!getResult.records || getResult.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${payload.email}`);
  }

  const record = getResult.records[0];
  const recordId = record.id;

  // Step 2: Build fields to patch (only non-empty values from payload for mapped fields)
  const fieldsToPatch: Record<string, unknown> = {};
  const mappedFields: (keyof JotformPayload)[] = ['name', 'phone', 'address'];

  for (const field of mappedFields) {
    const value = payload[field];
    if (value !== undefined && value !== null && value !== '') {
      fieldsToPatch[field] = value;
    }
  }

  // If no fields to patch, we could skip the PATCH, but the spec expects a PATCH call? The plan says PATCH only fields that are empty.
  // We'll still call PATCH with empty fields? The example shows PATCH with fields. If fieldsToPatch is empty, we can skip and return.
