const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

/**
 * Jotform to Airtable connector.
 * When a Jotform submission arrives, look up the Airtable record by email and PATCH only the fields that are non-empty in the payload.
 */

export interface ConnectorConfig {
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  baseId: string;
  /** Airtable table name (e.g., "Table 1") */
  tableName: string;
  /** Airtable API key (personal access token). Can also be provided via AIRTABLE_API_KEY env var. */
  apiKey?: string;
  /** Injected fetch implementation (for testing). Defaults to global fetch. */
  fetch?: typeof fetch;
}

export interface JotformPayload {
  email: string;
  name?: string;
  phone?: string;
  address?: string;
  [key: string]: unknown;
}

export interface HandleResult {
  recordId: string;
}

/**
 * Escapes a value for use in an Airtable filterByFormula string literal.
 * According to the spec, '+' must be escaped as '\\+'. Also escape backslashes and single quotes.
 */
function escapeFormulaValue(value: string): string {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\+/g, '\\+');
}

/**
 * Builds a filterByFormula string to match a record by email.
 * Formula: {email} = 'escapedValue'
 */
function buildFilterByFormula(email: string): string {
  const escaped = escapeFormulaValue(email);
  return `{email} = '${escaped}'`;
}

async function airtableGet(
  config: ConnectorConfig,
  filterByFormula: string,
  fetchImpl: typeof fetch
): Promise<{ records: Array<{ id: string; fields: Record<string, unknown> }>; offset?: string }> {
  const url = new URL(`https://api.airtable.com/v0/${config.baseId}/${encodeURIComponent(config.tableName)}`);
  url.searchParams.set('filterByFormula', filterByFormula);
  url.searchParams.set('maxRecords', '1');

  const response = await fetchImpl(url.toString(), {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Airtable GET failed: ${response.status} ${response.statusText} at ${url.toString()}`);
  }

  return response.json();
}

async function airtablePatch(
  config: ConnectorConfig,
  recordId: string,
  fields: Record<string, unknown>,
  fetchImpl: typeof fetch
): Promise<{ id: string; fields: Record<string, unknown> }> {
  const url = `https://api.airtable.com/v0/${config.baseId}/${encodeURIComponent(config.tableName)}/${recordId}`;

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  });

  if (!response.ok) {
    throw new Error(`Airtable PATCH failed: ${response.status} ${response.statusText} at ${url}`);
  }

  return response.json();
}

/**
 * Main entry point. Processes a Jotform submission payload, finds the matching Airtable record by email,
 * and patches non-empty fields (name, phone, address) from the payload.
 *
 * @param payload - The parsed Jotform submission payload (must contain email).
 * @param config - Connector configuration including Airtable credentials.
 * @returns The updated Airtable record ID.
 * @throws Error if email is missing, no matching record found, or Airtable API returns non-2xx.
 */
export async function handle(payload: JotformPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required field
  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email');
  }

  const fetchImpl = config.fetch ?? fetch;
  const apiKey = config.apiKey ?? process.env.AIRTABLE_API_KEY;
  if (!apiKey) {
    throw new Error('Airtable API key not provided. Set config.apiKey or AIRTABLE_API_KEY env var.');
  }

  const fullConfig: Required<ConnectorConfig, 'apiKey'> = { ...config, apiKey };

  // Step 1: Find record by email
  const filter = buildFilterByFormula(payload.email);
  const getResult = await airtableGet(fullConfig, filter, fetchImpl);

  if (!getResult.records || getResult.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${payload.email}`);
  }

  const record = getResult.records[0];
  const recordId = record.id;

  // Step 2: Build fields to patch (only non-empty values from payload for mapped fields)
  const fieldsToPatch: Record<string, unknown> = {};
  const mappedFields: (keyof JotformPayload)[] = ['name', 'phone', 'address'];

  for (const field of mappedFields) {
    const value = payload[field];
    if (value !== undefined && value !== null && value !== '') {
      fieldsToPatch[field] = value;
    }
  }

  // If no fields to patch, we could skip the PATCH, but the spec expects a PATCH call? The plan says PATCH only fields that are empty.
  // We'll still call PATCH with empty fields? The example shows PATCH with fields. If fieldsToPatch is empty, we can skip and return.
  if (Object.keys(fieldsToPatch).length === 0) {
    return { recordId };
  }

  // Step 3: Patch the record
  await airtablePatch(fullConfig, recordId, fieldsToPatch, fetchImpl);

  return { recordId };
}

